/* Shared score and three always-on goals for the active department. */
const ObjectiveUI=(()=>{
function render(){const M=R.objectives,c=state.countries[active],o=c.objectives,rows=M.rows(state,active,R.output),names={economy:'Economy',military:'Military',research:'R&D'},keys=Object.keys(o.completed),departments=new Set(keys.map(k=>M.catalog[k].department));
 const host=$('objectiveSummary');host.innerHTML=`<h2>Many ways to win</h2><p><strong>${esc(c.name)}: ${keys.length}/3 objectives · ${departments.size}/2 departments</strong></p><p>Complete any 3 objectives across at least 2 departments. All nine goals are always open: change direction whenever you want. Economy + R&D can win without attacking anyone. Only the teacher’s end-of-round results award objectives.</p>${state.victory.turn!==null?`<p class="victory-banner" role="status">🏆 Round ${state.victory.turn}: ${esc(state.victory.winners.map(country).join(', '))} ${state.victory.winners.length>1?'share victory':'wins'}! Continue playing to finish more objectives.</p>`:''}${o.wonTurn?`<p>This country completed its council challenge in round ${o.wonTurn}.</p>`:''}<details><summary>Class progress</summary><div class="objective-scoreboard">${state.countries.map(k=>{const a=Object.keys(k.objectives.completed);return `<p>${esc(k.name)}: ${a.length} objectives · ${new Set(a.map(id=>M.catalog[id].department)).size} departments${k.objectives.wonTurn?' · 🏆 round '+k.objectives.wonTurn:''}</p>`;}).join('')}</div></details>`;
 const card=r=>`<article class="objective-card ${r.done?'earned':''}" data-objective="${r.key}"><h3>${r.done?'✓ ':''}${esc(r.name)}</h3><p>${esc(r.description)}</p><progress max="1" value="${r.done?1:r.progress}" aria-label="${esc(r.name)} progress"></progress><p class="objective-progress">${r.done?'Completed in round '+r.done:esc(r.detail)}</p>${!r.done&&r.ready?'<p>Ready for the teacher’s end-of-round check.</p>':''}<details><summary>How to help</summary><p>${esc(r.help)}</p></details></article>`;
 $('departmentObjectives').innerHTML=`<h2>${names[role]} objectives</h2><p>Each completed objective earns one permanent achievement for your country. No selection required. Streaks advance only after a full round and reset when a requirement is missed.</p>${rows.filter(r=>r.department===role).map(card).join('')}<details class="other-objectives"><summary>See the other departments’ objectives</summary>${rows.filter(r=>r.department!==role).map(r=>`<h3>${names[r.department]}</h3>`+card(r)).join('')}</details><p class="objective-footnote">Progress tracking began in round ${o.since}. Earlier research and trades are not counted retroactively. Army and civilian food are required for sustained economic goals; army food is required for military goals. Production value uses money/food ×1, wood ×2 and metal ×3.</p>`;
}
return {render};
})();
